<?php
namespace App\Controllers;
use App\Core\Database;
final class OrderController{public function index():void{$db=Database::db();$status=$_GET['status']??'';$sql="SELECT o.*,COUNT(i.id) items FROM orders o LEFT JOIN order_items i ON i.order_id=o.id";$args=[];if(in_array($status,['pending','paid','failed','refunded'],true)){$sql.=" WHERE o.status=?";$args[]=$status;}$sql.=" GROUP BY o.id ORDER BY o.id DESC";$s=$db->prepare($sql);$s->execute($args);$orders=$s->fetchAll();$selected=null;$items=[];if(!empty($_GET['id'])){$q=$db->prepare('SELECT * FROM orders WHERE id=?');$q->execute([(int)$_GET['id']]);$selected=$q->fetch();if($selected){$q=$db->prepare('SELECT i.*,p.id photo_id,COALESCE(p.title,i.item_title,ps.name) title,COALESCE(p.preview_path,MIN(sp.preview_path)) preview_path,COALESCE(p.id,MIN(sp.id)) cover_id,COALESCE(e.name,se.name) event_name FROM order_items i LEFT JOIN photos p ON p.id=i.photo_id LEFT JOIN events e ON e.id=p.event_id LEFT JOIN photo_sets ps ON ps.id=i.set_id LEFT JOIN events se ON se.id=ps.event_id LEFT JOIN photos sp ON sp.set_id=ps.id WHERE i.order_id=? GROUP BY i.id');$q->execute([$selected['id']]);$items=$q->fetchAll();}}admin_view('admin/orders',['orders'=>$orders,'selected'=>$selected,'items'=>$items,'pageTitle'=>'Pedidos','adminSection'=>'orders']);}public function status():never{verify_csrf();$status=$_POST['status']??'';if(in_array($status,['pending','paid','failed','refunded'],true))Database::db()->prepare("UPDATE orders SET status=?,paid_at=IF(?='paid',COALESCE(paid_at,NOW()),paid_at) WHERE id=?")->execute([$status,$status,(int)($_POST['id']??0)]);redirect('/admin/pedidos?id='.(int)($_POST['id']??0));}}

